<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessageBox,ElMessage} from 'element-plus';import {request} from '@/integration/service';const rows=ref([]),status=ref('pending'),busy=ref(false);async function load(){rows.value=await request('/api/admin/registrations?status='+status.value);}async function review(r,result){try{await ElMessageBox.confirm(result==='approved'?'通过后，该用户可作为读者登录、维护头像简介和留言。不会获得创作或私人空间权限。':'拒绝这次注册申请？',r.username);}catch{return;}busy.value=true;try{await request('/api/admin/registrations/'+r.id,'PUT',{status:result});ElMessage.success('已处理');await load();}catch{}finally{busy.value=false;}}onMounted(load);
</script>
<template><div><span class="studio-eyebrow">KNOCK, KNOCK</span><h1>有人敲门</h1><p class="review-note">注册申请通过后才会创建读者账号。这里由你决定谁能加入。</p><el-radio-group v-model="status" @change="load"><el-radio-button value="pending">等待审核</el-radio-button><el-radio-button value="approved">已通过</el-radio-button><el-radio-button value="rejected">已拒绝</el-radio-button></el-radio-group><el-empty v-if="!rows.length" description="暂时没有申请"/><div class="registration-list"><el-card v-for="r in rows" :key="r.id"><header><h2>{{r.name}} <small>@{{r.username}}</small></h2><time>{{new Date(r.created).toLocaleString()}}</time></header><p>{{r.reason}}</p><div v-if="status==='pending'"><el-button type="primary" :disabled="busy" @click="review(r,'approved')">欢迎加入</el-button><el-button :disabled="busy" @click="review(r,'rejected')">拒绝申请</el-button></div></el-card></div></div></template>
<style scoped>.review-note{margin:18px 0 25px;font-size:13px;color:var(--studio-muted)}.registration-list{display:grid;gap:18px;margin-top:24px}.registration-list header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.registration-list h2{font-size:18px}.registration-list small,.registration-list time{font-size:11px;color:var(--studio-muted)}.registration-list p{white-space:pre-wrap;margin:20px 0;line-height:1.8}</style>
